from pathlib import Path
import json
root=Path(__file__).parent
logo='<svg class="logo" viewBox="0 0 48 48" aria-hidden="true"><path d="m24 7 18 9-18 9-18-9Z M6 23l18 9 18-9 M6 30l18 9 18-9"/></svg>'
slides=[
('intro','سرج QA', 'من متطلب متفرق<br/>إلى نتيجة معها دليل.', '''<p class="lead">مساحة واحدة لتنظيم الاختبار، تسجيل ما حدث، ومشاركة النتيجة بوضوح.</p><div class="flow"><div class="flow-step" data-reveal="1"><span class="num">01</span><strong>المطلوب</strong><span>ما الذي نتحقق منه؟</span></div><div class="flow-step" data-reveal="2"><span class="num">02</span><strong>اختباراتي</strong><span>كيف نجربه؟</span></div><div class="flow-step" data-reveal="3"><span class="num">03</span><strong>النتائج</strong><span>ما الذي حدث فعلًا؟</span></div></div><p class="keyboard">اضغط <kbd>Space</kbd> لكشف الفكرة التالية، ثم الانتقال للشريحة التالية.</p>''', 'عرّف سرج كمساحة عمل للمختبر، لا كبديل لحكمه. اضغط المسافة لإظهار المراحل الثلاث.',3),
('problem','01 · المشكلة','النتيجة تضيع<br/>إذا تفرّق دليلها.', '''<div class="split"><div><p class="statement">متطلب في ملف.<br/>ملاحظة في محادثة.<br/>وصورة بلا سياق.</p><p class="proof" data-reveal="1">يصعب معرفة: ماذا اختبرنا؟ وماذا بقي؟</p></div><div class="sheet" data-reveal="2"><h3>سرج يربطها في سجل واضح</h3><dl><dt>مصدر</dt><dd>القاعدة التي نختبرها</dd><dt>حالة</dt><dd>الخطوات والنتيجة المتوقعة</dd><dt>دليل</dt><dd>المشاهدة أو استجابة الخدمة</dd></dl></div></div>''','اشرح المشكلة دون ادعاء أرقام عن توفير الوقت. القيمة هي وصل المصدر بالحالة والدليل.',2),
('sources','02 · المطلوب','ابدأ بالمصدر،<br/>قبل أن تكتب الاختبار.', '''<p class="lead">أضف تعليمات المهمة، صور الواجهة، أو وصف خدمة النظام.</p><div class="sources"><div class="source" data-reveal="1">تعليمات مكتوبة<span class="type">Requirements</span></div><div class="source" data-reveal="2">صور موجودة<span class="type">Visual evidence</span></div><div class="source" data-reveal="3">وصف الخدمة<span class="type">OpenAPI</span></div></div><p class="proof">اقتراح الذكاء مسودة للمراجعة؛ ليس نتيجة اختبار ولا حقيقة مؤكدة.</p>''','الصورة مصدر ثابت. لا تدعي أن أداة سرج تختبر تفاعل الشاشة من صورة. اقتراح الذكاء يحتاج مراجعة.',3),
('case','03 · اختباراتي','حالة واضحة، يمكن تكرارها.', '''<div class="evidence-layout"><div><p class="lead">اكتب ما ستفعله، ثم ما تتوقع أن يحدث.</p><div class="sheet" data-reveal="1"><h3>مثال: إلغاء حجز مؤكد</h3><p>افتح الحجز ← اضغط إلغاء</p><p class="mint">المتوقع: يختفي من القائمة.</p></div><p class="small" data-reveal="2">كل خطوة في حقل مستقل، ويمكن تعديل الحالة قبل تجربتها.</p></div><div><figure class="picture pic-large"><a href="assets/checks.png" target="_blank" rel="noopener" aria-label="فتح صورة الاختبار بحجمها الأصلي"><img src="assets/checks.png" alt="لقطة موجودة من واجهة سرج: حالة إلغاء حجز مؤكد بخطوات وتوقع واضح"/></a></figure><p class="picture-label">لقطة تجربة سابقة · اضغط الصورة لتكبيرها.</p></div></div>''','لقطة من واجهة التجربة السابقة، محفوظة كما هي. اشرح فصل الخطوات عن النتيجة المتوقعة.',2),
('execute','04 · التجربة','جرّب بنفسك،<br/>أو شغّل الفحص المعتمد.', '''<div class="split"><div class="mode" data-reveal="1"><h3>تجربة يدوية</h3><p>نفّذ الخطوات في النظام.</p><p>سجّل ما شاهدته، وأرفق الدليل عند الحاجة.</p><span class="pill">تجربة سجّلها المختبِر</span></div><div class="mode" data-reveal="2"><h3>فحص خدمة آلي</h3><p>راجع الحالة واعتمدها أولًا.</p><p>حدّد الهدف والصلاحيات، ثم شغّل C# أو Dart.</p><span class="pill">نتيجة تنفيذ فعلية</span></div></div><p class="proof" data-reveal="3">فشل الاتصال «متعذر»؛ لا يصبح عيبًا في المنتج تلقائيًا.</p>''','المساران متكاملان. سرج ليس متصفحًا آليًا للشاشات. التنفيذ الآلي هنا HTTP فقط، مع موافقة الكتابة.',3),
('results','05 · النتيجة','نتيجة واضحة، ودليل معها.', '''<div class="evidence-layout"><div><div class="result" data-reveal="1"><span class="dot"></span><div><strong>سليم</strong><p>السلوك يطابق المتوقع.</p></div></div><div class="result" data-reveal="2"><span class="dot bad"></span><div><strong>ظهرت مشكلة</strong><p>فرق موثق يحتاج متابعة.</p></div></div><div class="result" data-reveal="3"><span class="dot blocked"></span><div><strong>متعذر</strong><p>سبب يمنعنا من إكمال الحكم.</p></div></div><p class="small">تقرير مقروء للمشاركة، وتفاصيل تقنية لمن يحتاجها.</p></div><div><figure class="picture pic-large"><a href="assets/results.png" target="_blank" rel="noopener" aria-label="فتح صورة النتيجة بحجمها الأصلي"><img src="assets/results.png" alt="لقطة نتيجة تجريبية سابقة في سرج تقارن المتوقع باختفاء الحجز بالفعلي ببقائه ظاهرًا"/></a></figure><p class="picture-label">تجربة سابقة، لا نتائج NZL-217 · اضغط للتكبير.</p></div></div>''','هذه لقطة اختبار إلغاء من مشروع تجريبي سابق لا من المهمة الحية. الحالات المتعذرة تحتاج تفسيرًا لا إخفاءً في الأرقام.',3),
('proof','06 · من التجربة الفعلية','حُفظ حجز<br/>بمغادرة قبل الوصول.', '''<div class="split"><div><span class="pill warn">عيب مؤكد في API التدريبية</span><div class="dates"><div class="date"><span>الوصول</span><strong>2026-12-15</strong></div><div class="date"><span>المغادرة</span><strong>2026-12-12</strong></div></div><p class="negative" data-reveal="1">−3 ليالٍ</p></div><div class="sheet"><h3>كيف أثبتنا الحفظ؟</h3><p data-reveal="2">إنشاء الحجز أعاد <b dir="ltr">200</b> ومعرّفًا.</p><div class="line"></div><p data-reveal="3">قراءة مستقلة أعادت التاريخين نفسيهما.</p><p class="small">إنشاء ثم قراءة: دليلان على عيب واحد.</p></div></div><p class="small">التحقق مستقل عن محرك سرج · NZL-217 · 10 نوفمبر 2026. لا يثبت أن API هي خلفية صور الكونسول.</p>''','المعرف التاريخي 4618 موثق في التقرير. لم نكرر أي طلب حي. لا تقل إن سرج اكتشفها آليًا: غياب Accept في المحرك تطلب تحققًا مستقلاً.',3),
('standard','07 · نقطة القوة','توحيد طريقة العمل،<br/>لا توحيد الأحكام.', '''<p class="lead">نفس المعاني والحقول، مهما اختلف مصدر الاختبار أو لغة التشغيل.</p><table class="matrix"><thead><tr><th>ما الذي نوحّده؟</th><th>ماذا يكسب الفريق؟</th></tr></thead><tbody><tr data-reveal="1"><td>المصدر ← الحالة ← الدليل</td><td>يمكن تتبّع سبب كل اختبار.</td></tr><tr data-reveal="2"><td>المتوقع / الفعلي / الحالة</td><td>نتائج أسهل في المقارنة والمراجعة.</td></tr><tr data-reveal="3"><td>عقد تنفيذ مشترك لـ C# و Dart</td><td>نفس تنظيم المخرجات والتقارير.</td></tr></tbody></table><p class="proof">Standardization = طريقة عمل متسقة؛ لا شهادة مطابقة ولا ضمان لجودة النظام.</p>''','اشرح standardization بوضوح: توحيد الحقول والدلالات وعقد تشغيل موحد، لا ادعاء شهادة ISO أو امتثال رسمي.',3),
('modes','08 · التجربة والتسليم','مساحة تجربة محلية.<br/>ونسخة خاصة منفصلة.', '''<div class="split"><div class="mode" data-reveal="1"><h3>محلي · للتجربة</h3><p>ابدأ التجربة مباشرة، دون تسجيل دخول.</p><p>بيانات تعليمية منفصلة، ومهمة جاهزة للتجربة.</p><span class="pill">محلي بلا حساب · بيانات المالك غير منقولة</span></div><div class="mode" data-reveal="2"><h3>منشور · للمالك</h3><p>دخول Google وصلاحية المالك فقط.</p><p>لا يعرض بياناته للزائر أو للنسخة المحلية.</p><span class="pill">دخول Google مخصص للمالك</span></div></div><p class="proof">مساعد Cloudflare اختياري بحصة يومية؛ يقترح، ولا يحكم على النتيجة.</p>''','النسخة المحلية بلا دخول وببيانات تعليمية منفصلة؛ تحقق 15 فحصًا مستقلاً للعزل والحفاظ على الملاحظة اليدوية بعد التخطي. اختبارات Google على نقل مصطنع، ليست جلسة دخول Google حقيقية. عامل Cloudflare منشور وطلب نص بسيط نجح، لكن رحلة المساعد من الواجهة لا تزال قيد التحقق.',2),
('close','09 · الخلاصة','اختبار واضح.<br/>دليل مربوط.<br/><span class="mint">وقرار أسهل للمراجعة.</span>', '''<div class="endcap"><div data-reveal="1">المصدر يشرح<br/>لماذا نختبر.</div><div data-reveal="2">الخطوات توضّح<br/>كيف نجرّب.</div><div data-reveal="3">الدليل يثبت<br/>ما الذي حدث.</div></div><p class="small" style="margin-top:50px">اكتشفنا قصورًا وأصلحناه في المحرك وعرض النتائج؛ أدلة المحاولة الأصلية محفوظة.</p><p class="keyboard">انتهى العرض · ارجع بالأسهم أو استخدم وضع المقدم لعرض الملاحظات.</p>''','التحقق المستقل السابق يبقى يدويًا في سجله التاريخي. إصلاح Accept في C# وDart وإصلاح عرض التخطي وملخص المتعذر والمراجعة تغييرات لاحقة، ولا تحوّل المحاولة الأصلية إلى نجاح آلي بأثر رجعي.',3)
]
manifest={'slides':[{'sceneId':s[0],'notes':s[4],'fragments':[i*10+j for j in range(1,s[5]+1)]} for i,s in enumerate(slides)]}
island='<script type="application/hyperframes-slideshow+json">'+json.dumps(manifest,ensure_ascii=False)+'</script>'
parts=[]
for i,(id,label,title,body,note,nfr) in enumerate(slides):
    parts.append(f'<section id="{id}" class="slide clip" data-composition-id="{id}" data-start="{i*10}" data-duration="10" data-width="1920" data-height="1080" data-label="{label}"><header class="head"><span class="brand">{logo} SARJ</span><span class="section">{label}</span></header><h1>{title}</h1>{body}</section>')
composition='''<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>سرج · العرض</title><link rel="stylesheet" href="assets/deck.css"><script src="assets/gsap.min.js"></script></head><body>'''+island+'<div data-composition-id="root" data-start="0" data-duration="100" data-width="1920" data-height="1080"></div>'+''.join(parts)+'''<script>
(()=>{const scenes=[...document.querySelectorAll('.slide')];let current=-1;const root=gsap.timeline({paused:true});root.to({},{duration:100});window.__timelines=window.__timelines||{};window.__timelines.root=root;
function show(t){const next=Math.min(9,Math.max(0,Math.floor(t/10)));for(let i=0;i<scenes.length;i++){let active=i===next;scenes[i].classList.toggle('active',active);scenes[i].setAttribute('aria-hidden',String(!active));if(active){scenes[i].querySelectorAll('[data-reveal]').forEach(el=>el.classList.toggle('shown',t>=i*10+Number(el.dataset.reveal)-.01))}}current=next;document.body.dataset.slide=String(next+1);document.body.dataset.time=String(t);}
root.eventCallback('onUpdate',()=>show(root.time()));window.__hfSetTime=show;show(0);const post=()=>parent.postMessage({source:'hf-preview',type:'timeline',durationInFrames:3000,scenes:scenes.map(el=>({id:el.id,start:Number(el.dataset.start),duration:10}))},'*');window.addEventListener('load',()=>setTimeout(post,150));setTimeout(post,300);
})();</script></body></html>'''
(root/'composition/index.html').write_text(composition)
wrapper='''<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>سرج QA · عرض المشروع التفاعلي</title><style>@font-face{font-family:Brando;src:url('composition/assets/Brando-Regular.woff2')}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;background:#0a111a;color:#e6eef5;font-family:Brando,sans-serif}hyperframes-slideshow{display:block;position:relative;width:100vw;height:100dvh;outline:none}hyperframes-player{position:absolute;inset:0}noscript{padding:40px;display:block}</style><script src="composition/assets/hyperframes-player.global.js"></script><script src="composition/assets/hyperframes-slideshow.global.js"></script></head><body><hyperframes-slideshow tabindex="0" notes-storage-key="sarj-qa-evaluator-v1"><hyperframes-player interactive src="composition/index.html"></hyperframes-player>'''+island+'''</hyperframes-slideshow><noscript>يلزم تفعيل JavaScript لتشغيل العرض التفاعلي.</noscript><script>customElements.whenDefined('hyperframes-slideshow').then(()=>{const deck=document.querySelector('hyperframes-slideshow');deck.focus({preventScroll:true})});</script></body></html>'''
(root/'index.html').write_text(wrapper)
(root/'hyperframes.json').write_text(json.dumps({'name':'sarj-qa-presentation','entry':'composition/index.html','width':1920,'height':1080,'fps':30},indent=2))
